import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mapLimit } from './pool.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

test('顺序正确且并发峰值等于上限', async () => {
  let running = 0;
  let peak = 0;
  const out = await mapLimit([1, 2, 3, 4, 5, 6, 7, 8], 3, async (n) => {
    running += 1;
    peak = Math.max(peak, running);
    await sleep(30);
    running -= 1;
    return n * 2;
  });
  assert.deepEqual(out, [2, 4, 6, 8, 10, 12, 14, 16]);
  assert.equal(peak, 3, `并发峰值应为 3，实际 ${peak}`);
});

test('快的先完成也不打乱顺序', async () => {
  const out = await mapLimit([50, 10, 30], 3, async (ms) => {
    await sleep(ms);
    return ms;
  });
  assert.deepEqual(out, [50, 10, 30]);
});

test('边界输入', async () => {
  assert.deepEqual(await mapLimit([1, 2], 10, async (n) => n), [1, 2]);
  assert.deepEqual(await mapLimit([], 3, async () => 1), []);
});

test('抛错要透出去', async () => {
  await assert.rejects(
    () =>
      mapLimit([1, 2, 3], 2, async (n) => {
        if (n === 2) throw new Error('boom');
        return n;
      }),
    /boom/,
  );
});

test('并发是真的：8 个 30ms 任务、上限 4，总耗时明显小于串行', async () => {
  const t0 = Date.now();
  await mapLimit([1, 2, 3, 4, 5, 6, 7, 8], 4, async () => sleep(30));
  const ms = Date.now() - t0;
  assert.ok(ms < 150, `应在 150ms 内跑完（串行要 240ms+），实际 ${ms}ms`);
});

