import { test } from 'node:test';
import assert from 'node:assert/strict';
import { compare } from './semver.js';

test('主干按数字比', () => {
  assert.equal(compare('1.2.10', '1.2.9'), 1);
  assert.equal(compare('1.10.0', '1.9.0'), 1);
  assert.equal(compare('2.0.0', '10.0.0'), -1);
});

test('缺段补 0', () => {
  assert.equal(compare('1.2', '1.2.0'), 0);
  assert.equal(compare('1', '1.0.0'), 0);
  assert.equal(compare('1.2', '1.2.1'), -1);
});

test('前导 v 与空白', () => {
  assert.equal(compare('v1.2.3', '1.2.3'), 0);
  assert.equal(compare('  1.2.3 ', '1.2.3'), 0);
});

test('预发布小于正式版', () => {
  assert.equal(compare('1.2.0-alpha', '1.2.0'), -1);
  assert.equal(compare('1.2.0', '1.2.0-alpha'), 1);
});

test('预发布之间的比较', () => {
  assert.equal(compare('1.2.0-alpha.2', '1.2.0-alpha.10'), -1);
  assert.equal(compare('1.2.0-alpha', '1.2.0-beta'), -1);
  assert.equal(compare('1.2.0-rc.1', '1.2.0-rc.1'), 0);
  assert.equal(compare('1.2.0-alpha', '1.2.0-alpha.1'), -1);
  assert.equal(compare('1.2.0-1', '1.2.0-alpha'), -1);
});

test('build 元数据不参与比较', () => {
  assert.equal(compare('1.2.0+build.9', '1.2.0+build.1'), 0);
  assert.equal(compare('1.2.0-alpha+x', '1.2.0-alpha+y'), 0);
});

test('可直接用于 sort', () => {
  const sorted = ['1.2.0', '1.2.0-beta', '1.0.0', '1.2.0-alpha.2', '1.2.0-alpha.10'].sort(compare);
  assert.deepEqual(sorted, ['1.0.0', '1.2.0-alpha.2', '1.2.0-alpha.10', '1.2.0-beta', '1.2.0']);
});
